import {DataTable, Table, Blankslate} from '@primer/react/experimental'
import {Heading, Link, Stack} from '@primer/react'
import {useMemo} from 'react'
import {isFeatureEnabled} from '@github-ui/feature-flags'
import {useRouteQuery} from '@github-ui/react-core/future/use-route-query'
import {useIsStafftools} from '@github-ui/repos-rules/use-is-stafftools'
import {ssrSafeLocation} from '@github-ui/ssr-utils'
import styles from './BypassesByRepoTable.module.css'
import {useTimeSpan, InsightsTimeSpanMap} from '../contexts/TimeSpanContext'
import {
  dashboardRoute,
  orgDashboardRoute,
  stafftoolsDashboardRoute,
  stafftoolsOrgDashboardRoute,
} from '../routes/dashboard-route'

type DashboardRouteConfig =
  | typeof dashboardRoute
  | typeof orgDashboardRoute
  | typeof stafftoolsDashboardRoute
  | typeof stafftoolsOrgDashboardRoute

export function BypassesByRepoTable({routeConfig}: {routeConfig: DashboardRouteConfig}) {
  const {
    data: {bypassesByRepo, filter},
  } = useRouteQuery(routeConfig, 'mainQuery')

  const useCreatedFilter = isFeatureEnabled('rules_insights_filter_bar_created')
  const {timeSpan} = useTimeSpan()
  const isStafftools = useIsStafftools()

  const isActiveFilter = filter.evaluateStatus === 'active'

  const data = useMemo(() => {
    if (!bypassesByRepo) return []
    return bypassesByRepo.map(item => ({
      id: `${item.ownerLogin}/${item.repoName}`,
      repoName: item.repoName,
      ownerLogin: item.ownerLogin,
      count: item.count,
    }))
  }, [bypassesByRepo])

  if (!isActiveFilter) {
    return (
      <Stack gap="condensed">
        <Heading as="h2" className={styles.Heading}>
          Top repositories by bypasses
        </Heading>
        <Blankslate border>
          <Blankslate.Heading as="h3">This table is limited to Active rules only</Blankslate.Heading>
          <Blankslate.Description>
            Update the evaluate status filter to &quot;active&quot; to view bypasses by repository
          </Blankslate.Description>
        </Blankslate>
      </Stack>
    )
  }

  if (data.length === 0) {
    return (
      <Stack gap="condensed">
        <Heading as="h2" className={styles.Heading}>
          Top repositories by bypasses
        </Heading>
        <Blankslate border>
          <Blankslate.Heading as="h3">No bypasses found</Blankslate.Heading>
          <Blankslate.Description>
            No repositories have any rule bypasses for the selected filters
          </Blankslate.Description>
        </Blankslate>
      </Stack>
    )
  }

  return (
    <Stack gap="condensed">
      <Heading as="h2" className={styles.Heading}>
        Top repositories by bypasses
      </Heading>
      <p className={styles.Description}>
        Displays Rule Bypasses at the Organization, Repository, and Enterprise levels, limited to Active Rules only
      </p>
      <Table.Container>
        <DataTable
          aria-label="Top repositories by bypasses"
          data={data}
          columns={[
            {
              header: 'Repository',
              field: 'repoName',
              rowHeader: true,
              renderCell: row => {
                const basePath = isStafftools
                  ? `/stafftools/repositories/${row.ownerLogin}/${row.repoName}/repository_rules/insights`
                  : `/${row.ownerLogin}/${row.repoName}/settings/rules/insights`
                const url = new URL(basePath, ssrSafeLocation.origin)
                url.searchParams.set('rule_status', 'bypass')
                if (useCreatedFilter && filter.created) {
                  url.searchParams.set('created', filter.created)
                } else {
                  const timePeriod = InsightsTimeSpanMap[timeSpan] ?? 'week'
                  url.searchParams.set('time_period', timePeriod)
                }
                if (filter.evaluateStatus) url.searchParams.set('evaluate_status', filter.evaluateStatus)
                if (filter.branch && filter.branch !== 'all') url.searchParams.set('ref', filter.branch)
                if (filter.ruleset) url.searchParams.set('ruleset', filter.ruleset.name)
                return <Link href={url.pathname + url.search}>{row.repoName}</Link>
              },
            },
            {
              header: 'Bypasses',
              field: 'count',
              align: 'end',
            },
          ]}
        />
      </Table.Container>
    </Stack>
  )
}
