import {useCallback, useMemo} from 'react'
import {
  SecurityProductsFilterBar,
  createdFilterDefinition,
  evaluateStatusFilterDefinition,
  rulesetFilterDefinition,
  type FilterDefinition,
} from '@github-ui/repos-rules/SecurityProductsFilterBar'
import {useBranchFilterDefinitions} from '@github-ui/repos-rules/use-branch-filter-definitions'
import {encodePart} from '@github-ui/paths'
import type {SourceType} from '@github-ui/repos-rules/types/rules-types'
import type {DashboardFilter} from '../types'

/**
 * Builds the query-string portion of the dashboard URL from the current filter.
 * When `hasBranch` is true (repo-level), the branch param is always included:
 *   - A specific branch name scopes results to that branch.
 *   - "all" represents an unscoped/all-branches state (no branch selected).
 * When `hasBranch` is false (org-level), the branch param is omitted entirely.
 */
export function dashboardIndexPath({
  filter,
  hasBranch = true,
}: {
  filter?: DashboardFilter
  hasBranch?: boolean
}): string {
  const params: string[] = []
  if (filter) {
    if (hasBranch) {
      if (filter.branch !== undefined) {
        params.push(`ref=${encodePart(filter.branch)}`)
      } else {
        params.push('ref=all')
      }
    }
    if (filter.ruleset) params.push(`ruleset=${encodePart(filter.ruleset.name)}`)
    if (filter.evaluateStatus) params.push(`evaluate_status=${encodePart(filter.evaluateStatus)}`)
    if (filter.created) params.push(`created=${encodePart(filter.created)}`)
  }
  return params.length > 0 ? params.join('&') : ''
}

type DashboardFilterBarProps = {
  sourceType: SourceType
  source?: {ownerLogin: string; name: string}
  branchIsValid?: boolean
  filter: DashboardFilter
  rulesets: Array<{name: string}>
}

export function DashboardFilterBar({sourceType, source, branchIsValid, filter, rulesets}: DashboardFilterBarProps) {
  const {
    definitions: branchDefinitions,
    showBranchFilter,
    showKeyOnlyBranchFilter,
  } = useBranchFilterDefinitions<DashboardFilter>({
    sourceType,
    ownerLogin: source?.ownerLogin ?? '',
    repoName: source?.name ?? '',
    branchIsValid,
    filterBranch: filter.branch,
  })

  const filterDefinitions = useMemo<Array<FilterDefinition<DashboardFilter>>>(
    () => [
      createdFilterDefinition<DashboardFilter>(),
      ...branchDefinitions,
      rulesetFilterDefinition<DashboardFilter>(rulesets),
      evaluateStatusFilterDefinition<DashboardFilter>(),
    ],
    [branchDefinitions, rulesets],
  )

  const getIndexPath = useCallback(
    ({filter: f}: {filter?: DashboardFilter}) =>
      dashboardIndexPath({filter: f, hasBranch: showBranchFilter || showKeyOnlyBranchFilter}),
    [showBranchFilter, showKeyOnlyBranchFilter],
  )

  return (
    <SecurityProductsFilterBar<DashboardFilter>
      id="rule-insights-dashboard-filter"
      label="Filter rule insights dashboard"
      filter={filter}
      filterDefinitions={filterDefinitions}
      getIndexPath={getIndexPath}
    />
  )
}
