import {mainQuery} from '@github-ui/react-core/future/main-query'

import {ruleInsightsDashboardAppBuilder} from '../config/app-builder'

export type LayoutResponse = {}

const layoutQueries = [
  mainQuery<LayoutResponse>({
    queryDeps: ({pathname}) => ({pathname: `${pathname}/_layout`}),
  }),
] as const

export const layoutRoute = ruleInsightsDashboardAppBuilder.createQueryRouteConfig('layoutRoute', {
  path: '/:owner/:repo/settings/rules/dashboard',
  queries: [...layoutQueries],
})

export const orgLayoutRoute = ruleInsightsDashboardAppBuilder.createQueryRouteConfig('orgLayoutRoute', {
  path: '/organizations/:org/settings/rules/dashboard',
  queries: [...layoutQueries],
})

export const stafftoolsLayoutRoute = ruleInsightsDashboardAppBuilder.createQueryRouteConfig('stafftoolsLayoutRoute', {
  path: '/stafftools/repositories/:owner/:repo/repository_rules/dashboard',
  queries: [...layoutQueries],
})

export const stafftoolsOrgLayoutRoute = ruleInsightsDashboardAppBuilder.createQueryRouteConfig(
  'stafftoolsOrgLayoutRoute',
  {
    path: '/stafftools/users/:organizationId/organization_rules/dashboard',
    queries: [...layoutQueries],
  },
)
